const BAD:f64=-1.0e300;export fn half_wave_rectifier(a:[*c]const i64,n:usize)f64{if(a==null or n!=5)return BAD;const v=a[0..n];for(v[1..])|x|{if(x< -1000000 or x>1000000)return BAD;}switch(v[0]){0=>{if(v[1]<0 or v[2]<0 or v[3]<0 or (v[1]==0 and v[2]==0 and v[3]==0))return BAD;return @as(f64,@floatFromInt(v[4]))/@as(f64,@floatFromInt(v[1]+v[2]+v[3]));},1,2=>{if(v[2]!=0 or v[3]!=0 or v[4]!=0)return BAD;return @as(f64,@floatFromInt(v[1]))*0.318;},3=>{if(v[2]<=0 or v[3]!=0 or v[4]!=0)return BAD;return @as(f64,@floatFromInt(v[1]))/@as(f64,@floatFromInt(v[2]));},4,5=>{if(v[2]!=0 or v[3]!=0 or v[4]!=0)return BAD;return @as(f64,@floatFromInt(v[1]))/2.0;},else=>return BAD}}
